<div class="page-heading"><div><span class="section-kicker">MEMBERSHIP</span><h1>Membership nominations</h1><p>Potential members remain voters until an authorized reviewer approves and saves membership.</p></div></div><section class="card"><div class="card-body"><form method="get" action="<?= e(base_url('index.php')) ?>"><input type="hidden" name="page" value="membership_nominations"><?= select_field('status','Nomination status',['pending'=>'Pending review','approved'=>'Approved','rejected'=>'Rejected','superseded'=>'Enrolled separately'],$status,true) ?><button class="btn btn-outline-primary">Filter</button></form></div><div class="table-responsive"><table class="table"><thead><tr><th>Voter at nomination</th><th>Submitted (UTC)</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['voter_name_snapshot']) ?></td><td><?= e(date_display($row['created_at'],true)) ?></td><td><?= e(label($row['status'])) ?></td><td><a href="<?= e(url('membership_nomination',['id'=>$row['id']])) ?>">Review</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="4">No nominations in your current scope.</td></tr><?php endif; ?></tbody></table></div><div class="card-body"><?= number($total) ?> nominations · Page <?= $p ?> of <?= $last ?> <?php if($p>1): ?><a href="<?= e(url('membership_nominations',['status'=>$status,'p'=>$p-1])) ?>">Previous</a><?php endif; ?> <?php if($p<$last): ?><a href="<?= e(url('membership_nominations',['status'=>$status,'p'=>$p+1])) ?>">Next</a><?php endif; ?></div></section>
